// optimal way to find pivotstatic int findPivot(int nums[]){if(nums.length == 0) return;int low = 0;int high = nums.length - 1;if(nums[low] <= nums[high]) return high;while(low <= high){int mid = low + (high - low) / 2;if(high > mid && arr[mid] > arr[mid + 1]) return mid;if(low < mid && arr[mid] < arr[mid - 1]) return mid - 1;if(arr[low] <= arr[high]){low = mid + 1;}else{high = mid - 1;}